<script lang="ts">
  import type { Reservation } from '../api/types';
  import { prisonersOf, visitDateLabel } from '../utils/format';
  import { escapeHtml, openPrintWindow } from '../utils/print';
  import { ui } from '../store/ui.svelte';
  let { rows, date, printerName }: { rows: Reservation[]; date: string; printerName: string } = $props();
  const count = (v: unknown): number | null => v !== null && v !== undefined && String(v).trim() !== '' && Number.isInteger(Number(v)) && Number(v) >= 0 ? Number(v) : null;
  const tables = $derived(rows.slice().sort((a,b) => a.ref.localeCompare(b.ref)).map(r => {
    const adults = count(r.adultCount), young = count(r.childUnder5Count), children = count(r.child5to8Count), visitors = count(r.visitorCount);
    const prisoners = prisonersOf(r).length;
    return { ref: r.ref, adults, young, children, prisoners, people: visitors === null ? null : visitors + prisoners, review: adults === null || young === null || children === null || visitors === null || adults + young + children !== visitors };
  }));
  const totals = $derived(tables.reduce((s,r) => ({ people:s.people+(r.people??0), adults:s.adults+(r.adults??0), children:s.children+(r.children??0), young:s.young+(r.young??0), prisoners:s.prisoners+r.prisoners, review:s.review+Number(r.review) }), {people:0,adults:0,children:0,young:0,prisoners:0,review:0}));
  const metrics = $derived([{label:'โต๊ะทั้งหมด',value:tables.length},{label:'คนทั้งหมด',value:totals.people},{label:'ผู้ใหญ่ / มากกว่า 8 ปี',value:totals.adults},{label:'เด็ก 5–8 ปี',value:totals.children},{label:'เด็กต่ำกว่า 5 ปี',value:totals.young},{label:'ผู้ต้องขัง',value:totals.prisoners}]);
  function printReport() {
    const cells = tables.map(r => `<tr><td>${escapeHtml(r.ref)}</td><td>${r.people??'—'}</td><td>${r.adults??'—'}</td><td>${r.children??'—'}</td><td>${r.young??'—'}</td><td>${r.prisoners}</td><td>${r.review?'ตรวจสอบอายุ':'✓'}</td></tr>`).join('');
    const content = `<style>@page{size:A4 portrait;margin:12mm}.bakery-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.bakery-grid div{padding:14px;border:1px solid #d6c8b6;border-radius:10px;background:#fffaf2}.bakery-grid b{display:block;font-size:28px;color:#74492d}thead{display:table-header-group}tr{break-inside:avoid}</style><h2 style="font-size:24px;color:#74492d">ใบเตรียมขนมประจำวัน</h2><p>${escapeHtml(visitDateLabel(undefined,date))} · VIS + TBL ที่ยืนยันแล้ว</p><div class="bakery-grid">${metrics.map(m=>`<div>${m.label}<b>${m.value}</b></div>`).join('')}</div><p>คนทั้งหมดรวมผู้ต้องขัง กลุ่มอายุผู้ร่วมโต๊ะไม่ซ้ำกัน</p>${totals.review?`<p>ตรวจสอบข้อมูลอายุ ${totals.review} โต๊ะ ยอดรวมอาจยังไม่ครบ</p>`:''}<table><thead><tr><th>โต๊ะ / อ้างอิง</th><th>รวมคน</th><th>ผู้ใหญ่ / &gt;8 ปี</th><th>5–8 ปี</th><th>&lt;5 ปี</th><th>ผู้ต้องขัง</th><th>ตรวจสอบ</th></tr></thead><tbody>${cells}</tbody><tfoot><tr><th>รวม ${tables.length} โต๊ะ</th><th>${totals.people}</th><th>${totals.adults}</th><th>${totals.children}</th><th>${totals.young}</th><th>${totals.prisoners}</th><th></th></tr></tfoot></table><p style="margin-top:30px">ผู้จัดเตรียม ____________________ ผู้ตรวจรับ ____________________</p>`;
    if (!openPrintWindow(content,'ใบเตรียมขนมประจำวัน',printerName)) ui.showAlert({title:'กรุณาอนุญาต Popup',message:'อนุญาต Popup เพื่อเปิดรายงาน',type:'warning'});
  }
</script>
<section class="bakery" aria-label="รายงานเบเกอรี่ประจำวัน">
  <header><div><p class="eyebrow">BAKERY · DAILY PREPARATION</p><h3>ใบเตรียมขนมประจำวัน</h3><p>{visitDateLabel(undefined,date)} · การจอง VIS + TBL ที่ยืนยันแล้ว</p></div><button onclick={printReport} disabled={!date || !tables.length}>พิมพ์ / บันทึก PDF</button></header>
  <div class="metrics">{#each metrics as m (m.label)}<div><span>{m.label}</span><strong>{m.value.toLocaleString('th-TH')}</strong></div>{/each}</div>
  <p class="note">คนทั้งหมดรวมผู้ต้องขัง • จำนวนผู้ใหญ่และเด็กนับเฉพาะผู้ร่วมโต๊ะ • กลุ่มอายุไม่ซ้ำกัน</p>
  {#if totals.review}<p class="warning" role="status">ตรวจสอบข้อมูลอายุ {totals.review} โต๊ะก่อนเตรียมขนม ยอดรวมอาจยังไม่ครบ</p>{/if}
  {#if tables.length}<div class="table-wrap"><table><thead><tr><th>โต๊ะ / เลขอ้างอิง</th><th>รวมคน</th><th>ผู้ใหญ่ / &gt;8 ปี</th><th>5–8 ปี</th><th>&lt;5 ปี</th><th>ผู้ต้องขัง</th></tr></thead><tbody>{#each tables as r (r.ref)}<tr><td>{r.ref}{#if r.review}<small>ตรวจสอบข้อมูลอายุ</small>{/if}</td><td><b>{r.people??'—'}</b></td><td>{r.adults??'—'}</td><td>{r.children??'—'}</td><td>{r.young??'—'}</td><td>{r.prisoners}</td></tr>{/each}</tbody></table></div>{:else}<p class="empty">ไม่มีการจองที่ยืนยันแล้วในวันที่เลือก</p>{/if}
</section>
<style>
.bakery{border:1px solid #e4d6c5;border-radius:20px;background:#fffdf8;color:#513c2e;padding:24px;box-shadow:0 4px 20px #74492d08}.bakery header{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.eyebrow{font-size:10px;letter-spacing:.16em;color:#926c47;font-weight:700}.bakery h3{font-size:22px;font-weight:700;margin:6px 0}.bakery header p:last-child{font-size:13px;color:#806d5c}.bakery button{background:#74492d;color:white;border-radius:10px;padding:11px 18px;font-weight:600;font-size:13px;cursor:pointer}.bakery button:disabled{opacity:.45;cursor:default}.bakery button:focus-visible{outline:3px solid #ca9c67;outline-offset:3px}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin:22px 0 14px}.metrics div{background:#f6eee2;border-radius:12px;padding:16px 12px}.metrics span{font-size:12px}.metrics strong{display:block;font-size:30px;line-height:1.3;margin-top:9px;font-variant-numeric:tabular-nums}.note{font-size:12px;color:#806d5c}.warning{background:#fff0ce;padding:12px;border-radius:8px;margin-top:12px;font-size:13px}.table-wrap{overflow:auto;margin-top:20px}.bakery table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}.bakery th{text-align:left;background:#f6eee2;font-weight:600;padding:12px}.bakery td{padding:12px;border-bottom:1px solid #eee3d5}.bakery td:not(:first-child),.bakery th:not(:first-child){text-align:right}.bakery small{display:block;color:#9b5c17;font-size:11px}.empty{padding:28px;text-align:center;color:#806d5c}@media(max-width:1000px){.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:540px){.bakery{padding:16px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.bakery button{width:100%}}
</style>
